"""The fallback source: any ordinary article page."""
import re
import trafilatura
from .. import settings, textclean
from . import NeedsPaste, Source

BLOCK_INDICATORS = [
    'access to this page has been denied', 'access denied', 'you have been blocked',
    'please enable cookies', 'checking your browser', 'cloudflare', 'captcha',
    'enable javascript', 'robot or human', 'unusual traffic', 'verifying you are human',
    'verify you are human', 'enable cookies', 'browser check',
    'the request could not be satisfied', 'request blocked', 'reference #',
    'generated by cloudfront', 'http error 403', '403 forbidden',
]


def is_blocked(title, text):
    t = title.lower()
    if any(p in t for p in BLOCK_INDICATORS):
        return True
    both = (title + ' ' + text).lower()
    return len(text) < 500 and any(p in both for p in BLOCK_INDICATORS)


def body_from_html(html, url=''):
    """Article body from a page: paragraphs and block quotes in reading
    order, repeated paragraphs dropped. Returns (text, metadata dict)."""
    doc = trafilatura.bare_extraction(html, url=url or None, include_comments=False,
                                      include_tables=False, favor_precision=True)
    if doc is None:
        return '', {}
    body = doc.body if hasattr(doc, 'body') else doc['body']
    meta = doc.as_dict() if hasattr(doc, 'as_dict') else dict(doc)
    lines, seen = [], set()
    for el in body.iter('p', 'quote', 'head', 'item'):
        if el.tag != 'quote' and any(a.tag == 'quote' for a in el.iterancestors()):
            continue                      # text inside a quote is emitted with the quote
        text = re.sub(r'\s+', ' ', ''.join(el.itertext())).strip()
        if len(text) < 4:
            continue
        fingerprint = ' '.join(text.lower().split()[:8])
        if fingerprint in seen:
            continue
        seen.add(fingerprint)
        lines.append(('    ' + text) if el.tag == 'quote' else text)
    return '\n'.join(lines), meta


def clean_body(text, author=''):
    """Cut at the first ad marker, drop junk lines and blank lines."""
    for marker in settings.load()['ad_markers']:
        idx = text.find(marker)
        if idx != -1:
            text = text[:idx].rstrip()
            break
    text = textclean.apply_strip_lines(text, author)
    return re.sub(r'\n{2,}', '\n', text).strip()


class WebPage(Source):
    name, needs_page = 'webpage', True

    def matches(self, url, page):
        return True

    def fetch(self, url, page):
        html = page.html
        if len(html.strip()) < 200:
            raise NeedsPaste('The page is empty or needs JavaScript.')
        soup = page.soup
        text, meta = body_from_html(html, url)

        class _Doc:                                   # get_title's last-resort fallback
            def short_title(self):
                return re.sub(r'\s*[\-\|:]\s*.{3,40}$', '', meta.get('title') or '').strip()
        title = textclean.get_title(soup, _Doc())
        if is_blocked(title, text) or not text:
            raise NeedsPaste('The site appears to be blocking scraping.')
        # The extractor sometimes keeps the headline as the first body line;
        # the title is spoken separately, so it would be read twice.
        norm  = lambda t: re.sub(r'\W+', ' ', t).strip().lower()
        lines = text.split('\n')
        while lines and norm(lines[0]) == norm(title):
            lines.pop(0)
        text = '\n'.join(lines)
        author = (textclean.get_author(soup) or textclean.clean_author(meta.get('author') or '')
                  or 'Unknown Author')
        og = soup.find('meta', property='og:image')
        return {'kind': 'article', 'title': title, 'author': author,
                'site': textclean.get_site_name(soup, url), 'text': clean_body(text, author),
                'image_url': (og.get('content') if og and og.get('content') else None) or meta.get('image')}
